window.__gnExtra = {"exam-a1":{"level":"A1","minutes":81,"parts":{"P1":{"minutes":25,"tasks":[{"es":"Leé el mensaje que Rosa le escribió a Ana. Después respondé las tres preguntas.","passage":"Maitei, Ana. Mba'éichapa reiko?\nKo'ẽrõ pyhareve aháta nde rógape che sy ndive.\nJajotopáta.\nRosa","items":[{"id":"a1x.1","kind":"choice","area":"reading","label":"Leer un mensaje","q":"¿Adónde va a ir Rosa?","options":["A la casa de su mamá","A la casa de Ana","A la escuela"],"answer":2,"explain":"Rosa le escribe a Ana, y nde rógape es «a tu casa»: va a la casa de Ana. Che sy ndive dice con quién va, no adónde. La escuela no aparece."},{"id":"a1x.2","kind":"choice","area":"reading","label":"Leer un mensaje","q":"¿Cuándo va a ir?","options":["Hoy a la tarde","Mañana a la noche","Mañana a la mañana"],"answer":3,"explain":"Ko'ẽrõ es «mañana» y pyhareve, «a la mañana». Aháta, con -ta, dice que todavía no fue: lo va a hacer."},{"id":"a1x.3","kind":"choice","area":"reading","label":"Leer un mensaje","q":"¿Con quién va a ir?","options":["Con su mamá","Con Ana","Con su papá"],"answer":1,"explain":"Che sy ndive es «con mi mamá»: ndive, «con», va después de la persona. «Mi papá» sería che ru, y Ana es la amiga que la espera."}]}]},"P2":{"minutes":20,"tasks":[{"es":"Escuchá dos diálogos cortos. Cada uno suena dos veces. Elegí la respuesta correcta.","items":[{"id":"a1x.4","kind":"choice","area":"listening","label":"Qué escuchaste","q":"En la feria. ¿Qué pide el hombre?","audio":[["N","En la feria. ¿Qué pide el hombre?","En la feria. ¿Qué pide el hombre?"],["F","Mba'épa reipota?","¿Qué querés?"],["M","Mbohapy chipa ha peteĩ kesu, aguyje.","Tres chipás y un queso, gracias."]],"script":["Narrador: En la feria. ¿Qué pide el hombre?","Mujer: Mba'épa reipota?","Hombre: Mbohapy chipa ha peteĩ kesu, aguyje."],"options":["Dos chipás y un queso","Tres chipás y un queso","Tres quesos y un chipá"],"answer":2,"explain":"Mbohapy es «tres» y peteĩ, «uno»: pide tres chipás y un queso. «Dos» sería mokõi."},{"id":"a1x.5","kind":"choice","area":"listening","label":"Qué escuchaste","q":"Dos personas se conocen. ¿Con quién vive el hombre?","audio":[["N","Dos personas se conocen. ¿Con quién vive el hombre?","Dos personas se conocen. ¿Con quién vive el hombre?"],["F","Moõpa reiko?","¿Dónde vivís?"],["M","Aiko távape, che sy ha che ru ndive.","Vivo en la ciudad, con mi mamá y mi papá."]],"script":["Narrador: Dos personas se conocen. ¿Con quién vive el hombre?","Mujer: Moõpa reiko?","Hombre: Aiko távape, che sy ha che ru ndive."],"options":["Con su abuela","Solo","Con su mamá y su papá"],"answer":3,"explain":"Che sy ha che ru ndive es «con mi mamá y mi papá»: ndive, «con», va después de las personas. Aiko távape dice dónde vive: en la ciudad."}]}]},"P3":{"minutes":10,"tasks":[{"es":"Tu vecina no habla guaraní. ¿Qué 3 datos le pasarías?","passage":"Ko'ẽrõ pyhareve ndaipóri y.\nKo'ẽrõ ka'aru oĩta y.\nPeñongatu y ko árape.","points":[{"es":"Mañana a la mañana no va a haber agua.","key":true},{"es":"Hoy no hay agua en todo el día.","key":false},{"es":"Mañana a la tarde vuelve el agua.","key":true},{"es":"Mañana no va a haber agua en todo el día.","key":false},{"es":"Hay que guardar agua hoy.","key":true},{"es":"Hay que ir a buscar agua a la escuela.","key":false}]}]},"P4":{"minutes":15,"tasks":[{"es":"Rosa te escribe: «Maitei. Mba'éichapa reiko? Mba'épa rejapóta ko'ẽrõ?» Respondele con un mensaje de 20 a 30 palabras: contale cómo estás y qué vas a hacer mañana, preguntale algo y despedite.","samples":[{"level":"below","gn":"Maitei, Rosa. Iporã. Ko'ẽrõ amba'apo. Chau.","es":"Por debajo de A1: 6 palabras. Se entiende, pero cuenta un solo plan y no le pregunta nada a Rosa."},{"level":"at","gn":"Maitei, Rosa. Aiko porã, aguyje. Ha nde? Ko'ẽrõ pyhareve amba'apóta mbo'ehaópe. Ka'aru aháta che sy rógape. Ajapóta chipa hendive. Rehosépa chendive? Jajotopáta.","es":"A1: 22 palabras. Cumple todo con frases cortas y bien escritas: cómo está, sus planes con -ta (amba'apóta, aháta, ajapóta), una pregunta con -pa y la despedida."},{"level":"above","gn":"Maitei, Rosa. Aiko porã, aguyje. Ko'ẽrõ pyhareve amba'apóta mbo'ehaópe. Upéi aháta che sy rógape ajapo hag̃ua chipa hendive. Rehosépa chendive? Ndéve g̃uarã avei ajapóta. Jajotopáta.","es":"Por encima de A1: 25 palabras bien encadenadas. Ordena con upéi, dice para qué va con hag̃ua y suma ndéve g̃uarã («para vos»), formas de los niveles siguientes, sin errores."}]}]},"P5":{"minutes":11,"tasks":[{"es":"Presentate en un minuto: saludá, decí tu nombre, de dónde sos, con quién vivís y qué hacés. Grabate y después escuchate.","seconds":60,"samples":[{"level":"below","gn":"Hola. Che téra Carlos. Che… de Luque. Gracias.","es":"Por debajo de A1: solo dice su nombre, y con un error; lo demás, en castellano. Con che adelante, téra pasa a réra: Che réra Carlos."},{"level":"at","gn":"Mba'éichapa. Che réra Carlos. Che Paraguaigua. Aiko távape, che sy ha che ru ndive. Amba'apo mbo'ehaópe. Aguyje.","es":"A1: cumple la tarea con frases aprendidas. Saluda y dice su nombre, de dónde es, dónde y con quién vive y dónde trabaja."},{"level":"above","gn":"Maitei, mba'éichapa. Che réra Carlos ha che Paraguaigua. Ko'ág̃a aiko távape, che sy ha che ru ndive. Che mbo'ehára: amba'apo mbo'ehaópe pyhareve, ha ka'aru apurahéi. Ko'ẽrõ aháta che jarýi rógape ajapo hag̃ua chipa hendive. Aguyje.","es":"Por encima de A1: hace más de lo que pide la tarea. Describe su día (pyhareve, ka'aru), cuenta un plan (ko'ẽrõ) y dice para qué va con hag̃ua, una forma de los niveles siguientes. Todo seguido y sin errores."}]}]}},"rubric":[{"key":"cumplimiento","es":"Cumplimiento de la tarea"},{"key":"coherencia","es":"Coherencia"},{"key":"alcance","es":"Alcance"},{"key":"correccion","es":"Corrección"},{"key":"fluidez","es":"Fluidez (oral)"},{"key":"inteligibilidad","es":"Se entiende (oral)"}]},"placement":{"self":[{"id":"pl.s1","level":"A1","skill":"comp","es":"Entiendo saludos y preguntas simples sobre mi nombre o de dónde soy, si me hablan despacio."},{"id":"pl.s2","level":"A1","skill":"prod","es":"Puedo saludar, dar las gracias, despedirme y decir cómo me llamo y de dónde soy."},{"id":"pl.s3","level":"A2","skill":"comp","es":"Entiendo lo esencial de charlas cortas sobre compras, horarios o lugares, y de avisos simples por la radio."},{"id":"pl.s4","level":"A2","skill":"prod","es":"Puedo hacer una compra, preguntar un precio y contar en pocas frases qué hice o qué voy a hacer."},{"id":"pl.s5","level":"B1","skill":"comp","es":"Sigo las ideas principales de una charla o de la radio sobre temas que conozco, si hablan claro."},{"id":"pl.s6","level":"B1","skill":"prod","es":"Puedo conversar sin prepararme sobre temas de todos los días, contar algo que me pasó y dar mi opinión."},{"id":"pl.s7","level":"B2","skill":"comp","es":"Entiendo entrevistas y noticias de la radio sobre temas actuales, y distingo qué opina cada persona."},{"id":"pl.s8","level":"B2","skill":"prod","es":"Puedo defender una opinión con fluidez en una reunión y elegir mis palabras según quién me escucha."}],"items":[{"id":"pl.1","level":"A1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"Sos Ana. Una vecina te saluda. ¿Qué le respondés?","audio":[["F","Mba'éichapa reiko?","¿Cómo andás?"]],"script":["Mujer: Mba'éichapa reiko?"],"options":["Jajotopáta.","Iporã, ha nde?","Che réra Ana."],"answer":2,"explain":"La vecina pregunta cómo estás: Mba'éichapa reiko? Se responde Iporã, ha nde? («Bien, ¿y vos?»). Jajotopáta es para despedirse, y Che réra Ana responde a otra pregunta: Mba'éichapa nde réra?"},{"id":"pl.2","level":"A1","kind":"choice","area":"reading","label":"Qué dice el cartel","q":"Este cartel está en la puerta de una escuela. ¿Qué dice?","passage":"Tapeg̃uahẽ porãite","options":["Cerrado hasta mañana","No pasar","Bienvenidos"],"answer":3,"explain":"Tapeg̃uahẽ porãite da la bienvenida a todos los que llegan. No dice nada de cerrar ni de no pasar. A una sola persona se le dice Tereg̃uahẽ porãite."},{"id":"pl.3","level":"A2","kind":"choice","area":"listening","label":"Qué escuchaste","q":"Una mujer llama a un amigo por teléfono. ¿Dónde está él ahora?","audio":[["F","Moõpa reime ko'ág̃a?","¿Dónde estás ahora?"],["M","Ag̃uahẽma che rógape. Ka'aru aháta mbo'ehaópe.","Ya llegué a mi casa. A la tarde voy a ir a la escuela."]],"script":["Mujer: Moõpa reime ko'ág̃a?","Hombre: Ag̃uahẽma che rógape. Ka'aru aháta mbo'ehaópe."],"options":["En su casa","En la escuela","En el trabajo"],"answer":1,"explain":"Ag̃uahẽma che rógape es «ya llegué a mi casa»: ahí está ahora. A la escuela va a ir a la tarde: ka'aru aháta mbo'ehaópe. Del trabajo no dice nada."},{"id":"pl.4","level":"A2","kind":"choice","area":"reading","label":"Leer un mensaje","q":"Rosa te manda este mensaje. ¿Qué hizo ya?","passage":"Ajapóma chipa che sy ndive. Ko'ẽrõ aháta ajogua kesu.","options":["Compró queso.","Hizo chipá con su mamá.","Comió chipá con su mamá."],"answer":2,"explain":"Ajapóma, con -ma, es «ya hice»: ya hizo chipá con su mamá (che sy ndive). Para «comí» diría ha'u. El queso lo va a comprar mañana: ko'ẽrõ aháta ajogua kesu."},{"id":"pl.5","level":"B1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"Un compañero de trabajo te deja un mensaje de voz. ¿Qué te dice?","audio":[["M","Ko árape ndahái amba'apo, che sy hasýgui.","Hoy no voy a trabajar porque mi mamá está enferma."],["M","Apytáta hendive.","Me voy a quedar con ella."],["M","Ko'ẽrõ amba'apo jeýta.","Mañana vuelvo a trabajar."]],"script":["Hombre: Ko árape ndahái amba'apo, che sy hasýgui.","Hombre: Apytáta hendive.","Hombre: Ko'ẽrõ amba'apo jeýta."],"options":["Hoy no trabaja porque él está enfermo.","Hoy trabaja, y mañana se queda con su mamá.","Su mamá está enferma, y mañana la lleva al médico.","Hoy se queda con su mamá enferma, y mañana vuelve a trabajar."],"answer":4,"explain":"Ko árape ndahái amba'apo, che sy hasýgui: hoy no va a trabajar porque su mamá está enferma. La enferma es ella, no él. Apytáta hendive: se queda con ella. Ko'ẽrõ amba'apo jeýta: mañana vuelve a trabajar. Del médico no dice nada."},{"id":"pl.6","level":"B1","kind":"choice","area":"reading","label":"Leer un relato","q":"Leé lo que cuenta Luis. ¿Qué pasó con el queso?","passage":"Kuehe ka'aru aha ñemuhápe ajogua hag̃ua kesu. Ag̃uahẽ jave, ndaipóri kesu. Upéi aha che sy rógape, ha che sy ome'ẽ chéve peteĩ kesu.","options":["Lo compró en el negocio.","Lo compró otro día.","Se lo dio su mamá.","No consiguió queso."],"answer":3,"explain":"En el negocio no había queso: ag̃uahẽ jave, ndaipóri kesu («cuando llegué, no había queso»). Después fue a la casa de su mamá, y ella le dio uno: che sy ome'ẽ chéve peteĩ kesu. Así que consiguió queso, pero no lo compró: ni en el negocio ni otro día."}],"production":{"es":"Presentate en guaraní en unos 30 segundos: tu nombre, de dónde sos y qué hacés. Si te falta una palabra, decila en castellano y seguí.","seconds":45}},"reader":{"works":[{"id":"rd.ana","title":"Che jarýi róga","es":"La casa de mi abuela","level":"A1","about":"Ana va a la casa de su abuela, saluda a su familia y la abuela invita a tomar tereré.","phrases":[{"t":"Che réra","tail":" ","words":[{"t":"Che","m":[["che","mi","r"]],"e":"mi"},{"t":"réra","m":[["réra","nombre","r"]],"e":"nombre"}],"g":["che + réra","me llamo (mi nombre)"],"n":"téra (nombre) se vuelve réra después de che. No hace falta un verbo: che réra Ana."},{"t":"Ana","tail":". ","words":[{"t":"Ana","m":[["Ana","nombre de mujer","r"]],"e":"Ana (nombre)"}],"g":null},{"t":"Aha","tail":" ","words":[{"t":"Aha","m":[["a-","yo","p"],["ha","ir","r"]],"e":"voy"}],"g":["a-","yo: quien habla"],"n":"Ir es irregular: aha (voy), reho (vas), oho (va)."},{"t":"che jarýi rógape","tail":". «","words":[{"t":"che","m":[["che","mi","r"]],"e":"mi"},{"t":"jarýi","m":[["jarýi","abuela","r"]],"e":"abuela"},{"t":"rógape","m":[["róga","casa (de alguien)","r"],["-pe","a, en","c"]],"e":"a la casa"}],"g":["-pe","a, en: el lugar"],"n":"óga (casa) se vuelve róga después de quien la tiene: che róga, che jarýi róga."},{"t":"Mba'éichapa","tail":", ","words":[{"t":"Mba'éichapa","m":[["mba'éicha","cómo","r"],["-pa","pregunta","s"]],"e":"¿cómo estás?"}],"g":["-pa","pregunta"],"n":"Literalmente «¿cómo?». Es el saludo de todos los días."},{"t":"che jarýi","tail":"?» «","words":[{"t":"che","m":[["che","mi","r"]],"e":"mi"},{"t":"jarýi","m":[["jarýi","abuela","r"]],"e":"abuela"}],"g":null,"n":"Lleva tilde porque la fuerza va en la ý, no en la i del final."},{"t":"Iporã","tail":", ","words":[{"t":"Iporã","m":[["i-","él, ella, eso","p"],["porã","bien, lindo","r"]],"e":"bien"}],"g":null,"n":"Así se contesta a Mba'éichapa. Literalmente «está bien»."},{"t":"ha","tail":" ","words":[{"t":"ha","m":[["ha","y","x"]],"e":"y"}],"g":null},{"t":"nde","tail":"?» «","words":[{"t":"nde","m":[["nde","vos","r"]],"e":"vos"}],"g":null,"n":"Ha nde? devuelve la pregunta: ¿y vos?"},{"t":"Iporã","tail":".» ","words":[{"t":"Iporã","m":[["i-","él, ella, eso","p"],["porã","bien, lindo","r"]],"e":"bien"}],"g":null},{"t":"Upéi","tail":" ","words":[{"t":"Upéi","m":[["upéi","después","r"]],"e":"después"}],"g":null},{"t":"amomaitei","tail":" ","words":[{"t":"amomaitei","m":[["a-","yo","p"],["momaitei","saludar","r"]],"e":"saludo"}],"g":["a-","yo: quien habla"],"n":"maitei es «saludo»; momaitei, «saludar»."},{"t":"che sy","tail":" ","words":[{"t":"che","m":[["che","mi","r"]],"e":"mi"},{"t":"sy","m":[["sy","madre","r"]],"e":"mamá"}],"g":null},{"t":"ha","tail":" ","words":[{"t":"ha","m":[["ha","y","x"]],"e":"y"}],"g":null},{"t":"che rúpe","tail":". ","words":[{"t":"che","m":[["che","mi","r"]],"e":"mi"},{"t":"rúpe","m":[["ru","padre","r"],["-pe","a","c"]],"e":"a papá"}],"g":["-pe","a: la persona que saludo"],"n":"ru + -pe se escribe rúpe: la fuerza sigue en ru y la tilde lo marca. Acá -pe va una sola vez, al final: che sy ha che rúpe."},{"t":"Che jarýi","tail":" ","words":[{"t":"Che","m":[["che","mi","r"]],"e":"mi"},{"t":"jarýi","m":[["jarýi","abuela","r"]],"e":"abuela"}],"g":null},{"t":"he'i","tail":": «","words":[{"t":"he'i","m":[["he'i","dice","r"]],"e":"dice"}],"g":null,"n":"Decir es irregular: he'i es «dice»."},{"t":"Ja'u","tail":" ","words":[{"t":"Ja'u","m":[["ja-","nosotros (con vos)","p"],["'u","comer, tomar","r"]],"e":"tomemos"}],"g":["ja-","nosotros, con vos (ñande)"],"n":"'u es comer y también tomar. Con ja- la abuela invita a todos: tomemos."},{"t":"terere","tail":"».","words":[{"t":"terere","m":[["terere","tereré","r"]],"e":"tereré"}],"g":null,"n":"En guaraní se escribe sin tilde: sin marca, la fuerza va al final."}]}]},"speaking":{"pairs":[["pyta","talón; quedarse","pytã","rojo","nasal"],["pytu","aliento","pytũ","oscuro","nasal"],["téra","nombre","térã","o (una cosa o la otra)","nasal"],["po'i","delgado, fino","poi","soltar","puso"],["mbo'y","collar","mboy","¿cuántos?","puso"],["ka'i","mono","kái","quemarse","puso"],["ita","piedra","yta","nadar","y"],["yvytu","viento","yvyty","cerro","y"]],"phrases":[{"gn":"Mba'éichapa?","es":"Hola, ¿cómo estás?"},{"gn":"Iporã, ha nde?","es":"Bien, ¿y vos?"},{"gn":"Che réra Ana.","es":"Me llamo Ana."},{"gn":"Mba'éichapa nde réra?","es":"¿Cómo te llamás?"},{"gn":"Aguyjevete.","es":"Muchas gracias."},{"gn":"Jajotopáta.","es":"Nos vemos."}]},"typing":{"letters":["ã","ẽ","ĩ","õ","ũ","ỹ","g̃","'"],"words":[{"gn":"mba'éichapa","es":"hola, ¿cómo estás?"},{"gn":"iporã","es":"bien"},{"gn":"jajotopáta","es":"nos vemos"},{"gn":"cheñyrõmi","es":"perdón, disculpá"},{"gn":"tereg̃uahẽ porãite","es":"bienvenida, bienvenido","accept":["tereguahẽ porãite","tereg̃uahẽporãite"]},{"gn":"ikatúpa aike","es":"¿puedo pasar?"},{"gn":"ñande","es":"nosotros (con vos)"},{"gn":"peẽ","es":"ustedes"},{"gn":"ha'e","es":"él, ella"},{"gn":"peteĩ","es":"uno"},{"gn":"pytũ","es":"oscuro"},{"gn":"tapỹi","es":"choza"}]}};
